const settings = $('Settings').first().json;
const norm = (arr) => (Array.isArray(arr) ? arr : (arr ? [arr] : [])).map((t) => String(t).toLowerCase());
const includeTags = norm(settings.include_tags);
const excludeTags = norm(settings.exclude_tags);
const pages = $input.all();
const convos = [];
for (const p of pages) {
  const body = p.json;
  const list = Array.isArray(body) ? body : (body.items || body.conversations || body.data || [body]);
  for (const c of list) if (c) convos.push(c);
}
const out = [];
for (const c of convos) {
  const cp = c.correspondentProfile || {};
  const leadTags = norm([...(cp.tags || []), ...(cp.autoTags || [])]);
  const included = includeTags.length === 0 || includeTags.some((t) => leadTags.includes(t));
  const excluded = excludeTags.some((t) => leadTags.includes(t));
  if (!included || excluded) continue;
  const linkedin_url = cp.profileUrl || c.leadProfileUrl || c.profileUrl || '';
  if (!linkedin_url) continue;
  const raw = c.messages || c.conversationMessages || c.chatMessages || [];
  const conversation_messages = raw.map((m) => ({
    direction: (m.sender === 'CORRESPONDENT' || m.sender === 'lead' || m.direction === 'incoming' || m.isFromLead === true) ? 'incoming' : 'outgoing',
    body: m.body || m.text || m.message || '',
    sent_at: m.createdAt || m.timestamp || null,
  })).filter((m) => m.body);
  out.push({ json: { linkedin_url, name: [cp.firstName, cp.lastName].filter(Boolean).join(' ').trim(), conversation_messages } });
}
return out;

const lead = $json;
const settings = $('Settings').first().json;
const conversation_messages = Array.isArray(lead.conversation_messages) ? lead.conversation_messages : [];
return { json: {
  campaign_id: settings.reengagement_campaign_id,
  contact: { linkedin_profile_url: lead.linkedin_url, conversation_messages },
  add_contact_to_campaign: true,
  linkedin_url: lead.linkedin_url,
  name: lead.name || '',
} };
